PRAGMA foreign_keys = ON;
CREATE TABLE configuracion (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE TABLE modulos (id TEXT PRIMARY KEY, activo INTEGER NOT NULL CHECK(activo IN (0,1)));
CREATE TABLE clientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, telefono TEXT NOT NULL DEFAULT '', ciudad TEXT NOT NULL DEFAULT '', estado TEXT NOT NULL DEFAULT 'Activo' CHECK(estado IN ('Activo','Potencial','Inactivo')));
CREATE TABLE productos (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, categoria TEXT NOT NULL, precio REAL NOT NULL CHECK(precio>=0), stock INTEGER NOT NULL CHECK(stock>=0), stock_minimo INTEGER NOT NULL DEFAULT 3 CHECK(stock_minimo>=0));
CREATE TABLE proveedores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, telefono TEXT NOT NULL DEFAULT '', especialidad TEXT NOT NULL);
CREATE TABLE componentes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, proveedor_id INTEGER NOT NULL REFERENCES proveedores(id) ON DELETE RESTRICT, precio REAL NOT NULL CHECK(precio>=0), stock INTEGER NOT NULL CHECK(stock>=0));
CREATE TABLE empleados (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, email TEXT NOT NULL UNIQUE, departamento TEXT NOT NULL, puesto TEXT NOT NULL, salario REAL NOT NULL CHECK(salario>=0));
CREATE TABLE pedidos (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE RESTRICT, fecha TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK(estado IN ('Pendiente','Confirmado','Entregado','Cancelado')), notas TEXT NOT NULL DEFAULT '');
CREATE TABLE lineaspedido (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE, producto_id INTEGER NOT NULL REFERENCES productos(id) ON DELETE RESTRICT, cantidad INTEGER NOT NULL CHECK(cantidad>0), precio_unitario REAL NOT NULL CHECK(precio_unitario>=0));
CREATE TABLE facturas (id INTEGER PRIMARY KEY AUTOINCREMENT, numero TEXT NOT NULL UNIQUE, pedido_id INTEGER NOT NULL UNIQUE REFERENCES pedidos(id) ON DELETE RESTRICT, fecha TEXT NOT NULL, vencimiento TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK(estado IN ('Pendiente','Pagada')), CHECK(vencimiento>=fecha));
CREATE TABLE actividad (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), accion TEXT NOT NULL, entidad TEXT NOT NULL, detalle TEXT NOT NULL);
CREATE VIEW resumen_pedidos AS SELECT p.*, c.nombre AS cliente, ROUND(COALESCE(SUM(l.cantidad*l.precio_unitario),0),2) AS total FROM pedidos p JOIN clientes c ON c.id=p.cliente_id LEFT JOIN lineaspedido l ON l.pedido_id=p.id GROUP BY p.id;
CREATE VIEW resumen_facturas AS SELECT f.*, p.cliente, p.total AS base, ROUND(p.total*0.21,2) AS iva, ROUND(p.total*1.21,2) AS total FROM facturas f JOIN resumen_pedidos p ON p.id=f.pedido_id;
CREATE INDEX idx_pedidos_cliente ON pedidos(cliente_id);
CREATE INDEX idx_lineas_pedido ON lineaspedido(pedido_id);
CREATE INDEX idx_lineas_producto ON lineaspedido(producto_id);
CREATE INDEX idx_componentes_proveedor ON componentes(proveedor_id);
PRAGMA user_version = 1;
